INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 24, 'theory', 'Quiz: backups and DR');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 0, 'What does the archive made by engine-backup contain?', '["The contents of all virtual machine disks", "Snapshots of the virtual machines", "The engine database and its configuration files", "ISO images and templates"]', 2, 'engine-backup protects the engine itself: the database and the configuration (optionally the DWH database too). Machine disks sit on storage and need a separate backup.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 1, 'Why does a virtual machine snapshot not replace a backup?', '["It lies on the same storage as the disk and dies with it", "It is always written to tape only", "It stores only the RAM", "It cannot be created for a running machine"]', 0, 'A snapshot is a layer on the same domain, so losing the domain destroys the disk and the snapshots; also the layer chain grows and slows things down.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 2, 'What happens when a disk''s bitmap becomes invalid, for example after an unclean shutdown of the machine?', '["The backup proceeds as usual", "The engine overwrites the disk", "The host reboots", "The backup fails: the invalid checkpoint is removed and the chain continues from a full backup"]', 3, 'An invalid bitmap cannot be detected in advance: it shows up when a backup starts, and the backup fails. The invalid checkpoint is removed and the chain usually restarts from a full backup, otherwise a restore would give corrupt data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 3, 'When is it sensible to transfer an image through the imageio proxy rather than directly to the host?', '["When maximum speed is needed", "When the client cannot reach the hosts and only the engine is accessible", "When the disk is raw", "When the machine has no snapshots"]', 1, 'The direct path is faster but needs network access to the hosts. The proxy on the engine is for an isolated client that sees only the engine, at the cost of speed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 4, 'How does the engine on the secondary site learn about the machines in an attached replicated domain?', '["From the primary site''s engine-backup archive", "From an OVA file of each machine", "From the descriptions in OVF_STORE on the domain itself, after which the machines are registered", "From virt-v2v"]', 2, 'Machine descriptions are stored in the domain''s own OVF_STORE service disks, so an attached domain carries what is needed to register the machines.');
